file.contenuto:
extends Node2D

@onready var sound_player: AudioStreamPlayer = $SoundPlayer
var coin_stream: AudioStream = preload("res://assets/audio/coin.wav")
var hit_stream: AudioStream = preload("res://assets/audio/hit.wav")


func _ready() -> void:
	sound_player.play()


func collect_coin() -> void:
	sound_player.stream = coin_stream
	sound_player.play()


func take_hit() -> void:
	sound_player.stream = hit_stream
	sound_player.play()

extends Node2D

@onready var music_player: AudioStreamPlayer = $MusicPlayer
@onready var coin_player: AudioStreamPlayer = $CoinPlayer
@onready var hit_player: AudioStreamPlayer = $HitPlayer


func _ready() -> void:
	music_player.play()


func collect_coin() -> void:
	coin_player.play()


func take_hit() -> void:
	hit_player.play()
